import React from 'react';
import { useParams } from 'react-router-dom';
import './BikeDetails.css';

const productData = {
  'yamaha-r15': {
    name: 'Yamaha R15',
    img: 'https://th.bing.com/th/id/OIP.HcWOj4BLgFs5NlEwOL7pYAHaE8?w=274&h=183&c=7&r=0&o=5&pid=1.7',
    description: 'A stylish and powerful sportbike known for its performance and sleek design.',
    price: '₹1,80,000',
    availableFor: ['Buy', 'Rent'],
  },
  'royal-enfield-classic-350': {
    name: 'Royal Enfield Classic 350',
    img: 'https://th.bing.com/th/id/OIP.HcWOj4BLgFs5NlEwOL7pYAHaE8?w=274&h=183&c=7&r=0&o=5&pid=1.7',
    description: 'A legendary cruiser with timeless design and a thumping engine.',
    price: '₹2,10,000',
    availableFor: ['Buy'],
  },
  // Add other entries following this pattern...
};

function ProductDetail() {
  const { productId } = useParams();
  const product = productData[productId];

  if (!product) {
    return <div className="product-detail"><h2>Product not found</h2></div>;
  }

  return (
    <div className="product-detail">
      <img src={product.img} alt={product.name} />
      <h2>{product.name}</h2>
      <p>{product.description}</p>
      <p><strong>Price:</strong> {product.price}</p>
      <p><strong>Available For:</strong> {product.availableFor.join(', ')}</p>
    </div>
  );
}

export default ProductDetail;
